mapper.update:
update student
name = #{name}, no = #{no}, gender = #{gender}, phone = #{phone}, degree = #{degree}, id_card = #{idCard}, is_college = #{isCollege}, address = #{address}, graduation_date = #{graduationDate}, clazz_id = #{clazzId},
where id = #{id}

update student
set violation_count = violation_count + 1,
violation_score = violation_score + #{score}
where id = #{id}

mapper.select:
SELECT stu.id, stu.name, stu.no, stu.gender, stu.phone, stu.degree, stu.id_card as idCard, stu.is_college as isCollege, stu.address, stu.graduation_date as graduationDate, stu.violation_count, stu.violation_score, stu.clazz_id as clazzId, stu.create_time as createTime, stu.update_time as updateTime, clazz.name as clazzName FROM student stu LEFT JOIN clazz ON stu.clazz_id = clazz.id
AND stu.name LIKE CONCAT('%', #{name}, '%')
AND stu.degree = #{degree}
AND stu.clazz_id = #{clazzId}
